def changed_paths(before, after):
    def _diff(b, a, prefix):
        result = set()

        if not (isinstance(b, dict) and isinstance(a, dict)):
            if b != a:
                result.add(prefix)
            return result

        for key in set(b.keys()) | set(a.keys()):
            key_path = f"{prefix}.{key}" if prefix else str(key)

            if key in b and key not in a:
                result.add(key_path)
            elif key not in b and key in a:
                result.add(key_path)
            else:
                result |= _diff(b[key], a[key], key_path)

        return result

    return sorted(_diff(before, after, ""))
```

