def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals (start, end).

    - Discards empty intervals (start == end).
    - Raises ValueError if any interval has start > end.
    - Returns a new sorted list of merged tuples; does not mutate the input.
    """
    cleaned = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")
        if start == end:
            continue
        cleaned.append((start, end))

    cleaned.sort()

    if not cleaned:
        return []

    result = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = result[-1]
        if start <= last_end:
            result[-1] = (last_start, max(last_end, end))
        else:
            result.append((start, end))

    return result
