def frames(lines):
    results = []
    data_values = []
    has_data = False

    for line in lines:
        if line == "":
            if has_data:
                results.append("\n".join(data_values))
            data_values = []
            has_data = False
        elif line.startswith("data:"):
            value = line[5:]
            if value.startswith(" "):
                value = value[1:]
            data_values.append(value)
            has_data = True
        # All other lines (comments, other fields, bare "data" without colon) are ignored

    return results
