from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two dictionaries into a deep-independent result.

    Overlay values replace base values (including lists and None).
    A None value does not delete a key.
    Inputs are not mutated and the result shares no nested references
    with either input.
    """
    result = {}

    for key in base:
        if key in overlay:
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = deepcopy(overlay_val)
        else:
            result[key] = deepcopy(base[key])

    for key in overlay:
        if key not in base:
            result[key] = deepcopy(overlay[key])

    return result
