def flatten(value):
    if not value:
        return {}
    result = {}
    for key, val in value.items():
        if isinstance(val, dict):
            if val:
                flat = flatten(val)
                for k, v in flat.items():
                    result[f"{key}.{k}"] = v
            else:
                result[key] = {}
        else:
            result[key] = val
    return result
