def normalize(path):
    """Normalize an absolute POSIX-like path.

    Rules:
      - Must start with '/', else ValueError.
      - Collapses repeated slashes.
      - Ignores '.' components.
      - Resolves '..' without going above root.
      - Returns '/' for the root.
      - No trailing slash on non-root results.
      - No filesystem access.
    """
    if not path.startswith('/'):
        raise ValueError(f"path must be absolute: {path!r}")

    stack = []
    for comp in path.split('/'):
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if stack:
                stack.pop()
        else:
            stack.append(comp)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

