def pack(items, max_bytes):
    """
    Greedily pack consecutive items into sublists whose total UTF-8
    byte length does not exceed max_bytes.
    """
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    if not items:
        return []

    byte_lengths = [len(item.encode("utf-8")) for item in items]

    for item, blen in zip(items, byte_lengths):
        if blen > max_bytes:
            raise ValueError(
                f"Item of {blen} UTF-8 bytes exceeds max_bytes={max_bytes}"
            )

    result = []
    current_batch = []
    current_sum = 0

    for item, blen in zip(items, byte_lengths):
        if current_sum + blen > max_bytes:
            if current_batch:
                result.append(current_batch)
            current_batch = [item]
            current_sum = blen
        else:
            current_batch.append(item)
            current_sum += blen

    if current_batch:
        result.append(current_batch)

    return result
```

