import heapq


def order(deps):
    # Collect all nodes: keys and all prerequisite values
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build in-degree map and reverse adjacency (who depends on whom)
    in_degree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):
            in_degree[node] += 1
            dependents[p].append(node)

    # Seed the min-heap with all currently ready nodes (in-degree 0)
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

